<!-- Swimming extension of Coach Watts' dashboard sections and Nuxt UI design. -->
<script setup lang="ts">
const route=useRoute()
const days=ref(28),environment=ref(''),end=ref(new Date().toLocaleDateString('sv-SE')),start=ref(''),resolution=ref('auto')
const filters=computed(()=>({days:days.value,start:start.value||undefined,resolution:resolution.value,environment:route.path==='/open-water'?'open_water':route.path==='/swimming'?'pool':environment.value,end:end.value||undefined}))
const {data:d,error,pending,refresh}=await useFetch<any>('/api/platform/summary',{query:filters})
const section=computed(()=>route.path)
const detailId=computed(()=>route.path.startsWith('/activity/')?route.path.split('/').pop():null)
const detail=ref<any>(null),detailError=ref('')
watch(detailId,async(id)=>{detail.value=null;detailError.value='';if(id)try{detail.value=await $fetch('/api/platform/activity/'+id)}catch(e:any){detailError.value=e.data?.error||'Dettaglio non disponibile'}},{immediate:true})
const fmt=(v:any,n=0)=>v==null?'—':Number(v).toLocaleString('it-IT',{maximumFractionDigits:n})
const pace=(value:any)=>{if(value==null)return '—';const s=Math.round(Number(value));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
const clock=(value:any)=>{if(value==null)return '—';const m=Math.round(Number(value)/60);return `${Math.floor(m/60)}h ${m%60}m`}
const health=computed(()=>d.value?.latest_health||{})
const cards=computed(()=>[
 {label:'Volume nuotato',value:d.value?.summary.distance_m==null?'—':fmt(d.value.summary.distance_m/1000,1),unit:'km',note:`${d.value?.summary.distance_n??0}/${d.value?.summary.sessions??0} sedute con distanza`,icon:'i-lucide-waves'},
 {label:'Sedute',value:d.value?.summary.sessions,unit:'nel periodo',note:`${d.value?.start??''} → ${d.value?.end??''}`,icon:'i-lucide-calendar-days'},
 {label:'HRV · ultimo dato',value:fmt(d.value?.latest_metrics?.hrv_ms?.value),unit:'ms',note:`Dato del ${d.value?.latest_metrics?.hrv_ms?.date||'non disponibile'}`,icon:'i-lucide-heart-pulse'},
 {label:'Sonno',value:clock(d.value?.latest_metrics?.sleep_total_s?.value),unit:'',note:`Ultimo dato: ${d.value?.latest_metrics?.sleep_total_s?.date||'non disponibile'}`,icon:'i-lucide-moon'}])
const css=computed(()=>{const tests=d.value?.css_tests||[];return tests.length?tests.toSorted((a:any,b:any)=>b.date.localeCompare(a.date))[0]:d.value?.css})
const message=ref('')
const post=async(url:string,body:any)=>$fetch<any>(url,{method:'POST',headers:{'x-csrf-token':d.value?.csrf||''},body})
async function refreshDetail(){if(detailId.value)detail.value=await $fetch('/api/platform/activity/'+detailId.value)}
const syncState=ref<any>(null)
async function loadSync(){try{syncState.value=await $fetch('/api/platform/sync')}catch{}}
async function sync(){message.value='';try{syncState.value=await post('/api/platform/sync',{});message.value='Sincronizzazione avviata. Lo storico resta conservato.'}catch(e:any){message.value=e.data?.error||'Sincronizzazione non disponibile'}}
let syncTimer:any
onMounted(()=>{loadSync();syncTimer=setInterval(()=>{if(route.path==='/data')loadSync()},4000)})
onUnmounted(()=>clearInterval(syncTimer))
const draft=ref<any>({title:'Nuoto endurance',date:new Date().toLocaleDateString('sv-SE'),goal:'',blocks:[{label:'Riscaldamento',reps:1,distance_m:400,zone:'Z1',rest_s:20},{label:'Serie principale',reps:6,distance_m:200,zone:'Z2',rest_s:20},{label:'Defaticamento',reps:1,distance_m:200,zone:'Z1',rest_s:0}]})
const preview=ref<any>(null),library=ref<any[]>([]),selectedTemplate=ref('')
onMounted(async()=>{try{const b=await $fetch<any>('/api/platform/builder');library.value=b.library}catch{}})
function loadTemplate(){const t=library.value.find(x=>x.id===selectedTemplate.value);if(!t)return;draft.value.title=t.nameEn||t.name;draft.value.goal=t.descriptionEn||t.description;draft.value.blocks=['warmupTemplate','mainSetTemplate','cooldownTemplate'].flatMap((k,i)=>(t[k]||[]).filter((b:any)=>b.distanceM).map((b:any)=>({label:['Riscaldamento','Serie principale','Defaticamento'][i],reps:b.repetitions||1,distance_m:b.distanceM,zone:(b.zone||'Z2').split('-')[0],rest_s:parseInt(b.recoveryEn||b.recovery)||0})));preview.value=null}
async function makePreview(){message.value='';try{preview.value=await post('/api/platform/builder',draft.value)}catch(e:any){message.value=e.data?.error||'Verifica i campi'}}
async function savePreview(){try{await post('/api/platform/builder',{kind:preview.value.preview.protocol?'css-tests':'workouts',confirm:true,preview_token:preview.value.preview_token});preview.value=null;message.value='Salvato nella memoria locale dell’atleta.';await refresh()}catch(e:any){message.value=e.data?.error||'Salvataggio non riuscito'}}
const test=ref<any>({kind:'css-tests',date:new Date().toLocaleDateString('sv-SE'),t400:null,t200:null,pool:25,maximal:false})
async function testCss(){try{preview.value=await post('/api/platform/builder',test.value)}catch(e:any){message.value=e.data?.error||'Verifica il test'}}
const activeLaps=computed(()=>detail.value?.laps?.filter((r:any)=>!r.is_rest)||[])
</script>

<template>
 <div class="space-y-6 max-w-[1600px] mx-auto w-full pb-12">
  <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="eyebrow mb-2">IL TUO ALLENAMENTO, NEL TEMPO</p><h1 class="text-2xl sm:text-3xl font-bold tracking-tight">{{section==='/'?'Benvenuto.':section==='/swimming'?'Dentro ogni vasca.':section==='/open-water'?'La distanza, senza muri.':section==='/recovery'?'Carico, riposo e risposta.':section==='/calendar'?'Il tuo calendario.':section==='/builder'?'Costruisci la prossima seduta.':section==='/coach'?'Il coach conosce il tuo storico.':section==='/data'?'Il tuo archivio Garmin.':'Analisi della seduta'}}</h1><p class="muted mt-2">Nuoto agonistico · endurance e acque libere · Garmin Fenix 8</p></div>
   <div v-if="!['/builder','/coach','/data'].includes(section)&&!detailId" class="space-y-3"><HistoryPeriod v-model:days="days" v-model:end="end" v-model:start="start" v-model:resolution="resolution"/><select v-if="!['/swimming','/open-water'].includes(section)" v-model="environment" aria-label="Ambiente"><option value="">Tutto il nuoto</option><option value="pool">Piscina</option><option value="open_water">Acque libere</option></select></div>
  </div>
  <UAlert v-if="error" color="error" title="Dati temporaneamente non disponibili" description="Il database può essere occupato durante l’import. Riprova tra poco."/><UButton v-if="error" @click="refresh()">Riprova</UButton>
  <p v-if="pending&&!d" class="muted">Lettura dell’archivio locale…</p>
  <UAlert v-if="message" :title="message" color="info" variant="subtle"/>

  <template v-if="d&&['/','/swimming','/open-water'].includes(section)">
   <MetricCards :items="cards"/>
   <div v-if="section==='/'" class="grid-main">
    <div class="panel"><p class="eyebrow mb-5">Profilo dell’atleta</p><h2 class="text-xl font-semibold">Nuoto · endurance</h2><p class="muted mt-2">Piscina 25/50 m e lunghe distanze in mare.</p><div class="grid grid-cols-2 gap-4 mt-6"><div><p class="eyebrow">FC a riposo</p><p class="text-xl font-semibold mt-1">{{fmt(health.resting_hr_bpm)}} <small class="muted">bpm</small></p></div><div><p class="eyebrow">Body Battery max</p><p class="text-xl font-semibold mt-1">{{fmt(health.body_battery_max)}} <small class="muted">/100</small></p></div></div><p class="muted mt-5">Dati del {{health.status_date}}. I valori mancanti restano non disponibili.</p></div>
    <div class="panel"><p class="eyebrow mb-5">La prossima decisione</p><h2 class="text-xl font-semibold">Parti dal carico recente.</h2><p class="muted mt-3 leading-relaxed">Consulta recupero, andamento delle sedute e programma prima di modificare i volumi. Il coach usa i calcoli verificati dello storico e distingue fatti e interpretazioni.</p><UButton to="/coach" color="primary" class="mt-5" icon="i-lucide-message-circle">Apri il coach</UButton><p class="text-xs text-zinc-500 mt-4">OpenAI tramite Codex è disponibile nel coach; lettura locale utilizzabile offline.</p></div>
    <div class="panel"><p class="eyebrow mb-5">Riferimenti di prestazione</p><p class="eyebrow text-purple-400">Critical Swim Speed</p><p class="metric mt-2">{{pace(css?.pace_100_s)}} <span class="muted">/100 m</span></p><p class="muted mt-2">{{css?`Prove del ${css.date||css.long_day} · vasca ${css.pool||css.pool_length_m} m`:'Test massimale 400/200 non disponibile.'}}</p><p class="text-xs text-amber-400 mt-3" v-if="css">Riferimento storico: verificare la validità per il carico attuale.</p><UButton to="/builder" color="neutral" variant="outline" class="mt-5">Aggiorna test e zone</UButton></div>
   </div>
   <div class="grid lg:grid-cols-3 gap-5"><HistoryChart class="lg:col-span-2" title="Volume nuotato" unit="km" :days="d.days" :history="d.volume_history" :fields="[{key:'km',label:'Distanza registrata',color:'#00dc82'}]" bar/><div class="panel"><p class="eyebrow mb-4">Qualità e contesto</p><p class="muted leading-relaxed">{{d.technical_note}}</p><p class="muted mt-4">{{d.pace_method}}</p><p v-if="section==='/open-water'" class="text-amber-300 text-sm mt-4">Il GPS in acqua può alterare distanza e passo. Nel dettaglio trovi lap e traccia temporale disponibili.</p><p class="muted mt-5">Archivio: {{fmt(d.inventory.swims)}} nuotate dal {{d.inventory.first_day}}.</p></div></div>
   <div v-if="section==='/swimming'" class="panel table-wrap"><h2 class="font-semibold mb-3">Tecnica · stile libero · gruppi omogenei</h2><p class="muted mb-4">SWOLF e cadenza sono separati per lunghezza vasca e modello di orologio. Nessun confronto automatico fra gruppi diversi.</p><table><thead><tr><th>Vasca</th><th>Orologio</th><th>Lap</th><th>SWOLF</th><th>Cadenza /min</th><th>Passo attivo</th><th>Copertura SWOLF</th></tr></thead><tbody><tr v-for="t in d.technique"><td>{{t.pool_length_m??'—'}} m</td><td>{{t.watch}}</td><td>{{t.laps_n}}</td><td>{{fmt(t.swolf,1)}}</td><td>{{fmt(t.cadence,1)}}</td><td>{{pace(t.pace_100_s)}} /100 m</td><td>{{t.swolf_n}}/{{t.laps_n}} lap</td></tr></tbody></table><p v-if="!d.technique?.length" class="muted mt-4">Nessun lap a stile libero disponibile nel periodo.</p></div><div v-if="section!=='/'" class="panel"><h2 class="font-semibold mb-4">Passo delle sedute · secondi /100 m</h2><TrendChart :rows="[...d.activities].reverse()" x="activity_date" :series="[{key:'session_pace_s',label:'Passo sessione (include eventuali pause)',color:'#60a5fa'}]"/></div>
  </template>


  <SwimComparison v-if="section==='/swimming'" :days="days" :end="end" :start="d?.start"/>
  <div v-if="d&&['/','/swimming','/open-water'].includes(section)" class="panel"><div class="flex justify-between mb-4"><h2 class="font-semibold">{{section==='/'?'Ultime attività':'Attività nel periodo'}}</h2><span class="muted">Apri una seduta per vasche e ripetute</span></div><div class="table-wrap"><table><thead><tr><th>Data / attività</th><th>Ambiente</th><th>Distanza</th><th>Tempo</th><th>Passo sessione</th><th>FC</th><th>SWOLF</th><th>FIT</th></tr></thead><tbody><tr v-for="a in (section==='/'?d.activities.slice(0,8):d.activities)" :key="a.activity_id"><td><NuxtLink :to="'/activity/'+a.activity_id" class="text-green-400 hover:underline">{{a.activity_date}} · {{a.name||a.activity_id}}</NuxtLink></td><td>{{a.environment==='pool'?`Vasca ${a.pool_length_m??'?'} m`:'Acque libere'}}</td><td>{{fmt(a.distance_m)}} m</td><td>{{clock(a.duration_s)}}</td><td>{{pace(a.session_pace_s)}} /100 m</td><td>{{fmt(a.avg_hr_bpm)}}</td><td>{{a.environment==='pool'?fmt(a.avg_swolf):'Non applicabile'}}</td><td>{{a.laps_n?`${a.laps_n} lap`:'Da elaborare'}}</td></tr></tbody></table><p v-if="!d.activities.length" class="muted py-8">Nessuna attività nel periodo selezionato.</p></div></div>

  <template v-if="detailId"><p v-if="detailError" class="text-amber-400">{{detailError}}</p><p v-if="!detail&&!detailError" class="muted">Caricamento dettaglio FIT…</p><template v-if="detail"><div class="panel"><UBadge>{{detail.summary.environment==='pool'?'Piscina':'Acque libere'}}</UBadge><h2 class="text-2xl font-bold mt-3">{{detail.summary.name}}</h2><p class="muted mt-1">{{detail.summary.activity_date}} · Garmin #{{detail.summary.activity_id}} · {{detail.summary.watch}}</p></div><MetricCards :items="[{label:'Distanza Garmin',value:fmt(detail.summary.distance_m),unit:'m'},{label:'Tempo attivo FIT',value:clock(detail.times?.active_s),note:detail.times?`${detail.times.active_lengths} vasche attive`:'Non disponibile'},{label:'Pause FIT',value:clock(detail.times?.rest_s),note:detail.times?`${detail.times.coverage_lengths} messaggi Length`:'Non disponibile'},{label:'SWOLF Garmin',value:detail.summary.environment==='pool'?fmt(detail.summary.avg_swolf):'N/A'}]"/>
   <div class="panel"><h2 class="font-semibold mb-4">Struttura letta dai lap</h2><p v-if="detail.times" class="text-green-400 mb-4">Distanza attiva FIT: {{fmt(detail.times.active_distance_m)}} m · passo attivo {{pace(detail.times.active_pace_100_s)}} /100 m</p><p class="muted" v-if="!detail.structure.available">{{detail.structure.why}}</p><div v-for="b in detail.structure.blocks||[]" :key="b.name" class="mt-4"><h3 class="text-green-400">{{b.name}} <small class="muted">· {{b.confidence}}</small></h3><p v-for="s in b.sets" class="text-sm mt-2">{{s.label}} · {{s.pace}} · recupero {{s.rest}} · dispersione {{s.spread}} · {{s.held}}</p></div><p v-for="s in detail.structure.sets||[]" class="text-sm mt-2">{{s.label}} · {{s.pace}} · {{s.held}}</p><p class="muted mt-4">La struttura è un’inferenza dichiarata. Le intenzioni e le correzioni manuali restano disponibili nel <a :href="'/sedute/'+detailId" class="text-green-400 underline">dettaglio analitico</a>.</p></div>
   <div class="panel"><h2 class="font-semibold mb-4">Passo per lap · secondi /100 m</h2><TrendChart :rows="activeLaps" x="lap_index" :series="[{key:'pace_per_100m_s',label:'Passo del lap',color:'#60a5fa'}]"/></div>
   <div v-if="detail.lengths.length" class="panel"><h2 class="font-semibold mb-4">Singole vasche</h2><TrendChart :rows="detail.lengths.filter((r:any)=>r.is_active)" x="length_index" :series="[{key:'pace_100_s',label:'Passo vasca',color:'#00dc82'}]"/><div class="table-wrap max-h-80 mt-5"><table><thead><tr><th>Vasca</th><th>Lap</th><th>Stile</th><th>Tempo s</th><th>Bracciate</th><th>Tipo</th></tr></thead><tbody><tr v-for="l in detail.lengths" :key="l.length_index"><td>{{l.length_index}}</td><td>{{l.lap_index}}</td><td>{{l.stroke||'—'}}</td><td>{{fmt(l.duration_s,1)}}</td><td>{{fmt(l.total_strokes)}}</td><td>{{l.is_active?'Nuotata':'Recupero'}}</td></tr></tbody></table></div></div>
   <SessionContextEditor :csrf="d?.csrf||''" :activity-id="detail.summary.activity_id" :annotation="detail.annotation" :laps="detail.laps" @saved="refreshDetail"/>
   <div v-if="detail.manual_structure?.length" class="panel table-wrap"><h2 class="font-semibold mb-3">Serie dichiarate e confermate dall’atleta</h2><table><thead><tr><th>Gruppo</th><th>Lap</th><th>Distanza attiva</th><th>Tempo attivo</th><th>Recuperi registrati</th><th>Passo attivo</th><th>Copertura</th></tr></thead><tbody><tr v-for="g in detail.manual_structure"><td>{{g.label}}</td><td>{{g.first_lap}}–{{g.last_lap}}</td><td>{{fmt(g.distance_m)}} m</td><td>{{clock(g.active_s)}}</td><td>{{clock(g.rest_s)}}</td><td>{{pace(g.pace_100_s)}} /100 m</td><td>{{g.pace_n}}/{{g.active_laps}} lap con tempo e distanza</td></tr></tbody></table></div>
   <div v-if="detail.open_water" class="panel space-y-4"><h2 class="font-semibold">Acque libere · distribuzione dello sforzo e qualità GPS</h2><p class="muted">{{detail.open_water.note}}</p><p v-if="detail.open_water.quality" class="text-sm">{{detail.open_water.quality.gps_points}}/{{detail.open_water.quality.points}} punti con GPS · intervallo mediano {{fmt(detail.open_water.quality.median_interval_s,1)}} s · {{detail.open_water.quality.segments_ok?'Controllo GPS superato':'Passo per segmenti non affidabile'}}</p><p v-if="detail.open_water.quality?.gate_reason" class="text-amber-300 text-sm">{{detail.open_water.quality.gate_reason}}</p><div class="grid lg:grid-cols-2 gap-4"><TrendChart :rows="detail.open_water.segments" x="label" :series="[{key:'pace_100_s',label:'Passo osservato · s/100 m'}]"/><TrendChart :rows="detail.open_water.segments" x="label" :series="[{key:'hr_bpm',label:'FC osservata · bpm',color:'#fb7185'}]"/></div><div class="table-wrap"><table><thead><tr><th>Finestra</th><th>Secondi nella finestra</th><th>Secondi con distanza appaiata</th><th>Distanza osservata</th><th>Passo /100 m</th><th>FC</th><th>Campioni FC / totali</th></tr></thead><tbody><tr v-for="g in detail.open_water.segments"><td>{{g.label}}</td><td>{{fmt(g.observed_s)}}</td><td>{{fmt(g.distance_observed_s)}} · {{g.distance_n}}/{{g.points_n}} campioni</td><td>{{fmt(g.distance_m)}} m</td><td>{{pace(g.pace_100_s)}}</td><td>{{fmt(g.hr_bpm)}}</td><td>{{g.hr_n}}/{{g.points_n}}</td></tr></tbody></table></div></div>
   <div v-if="detail.summary.environment==='open_water'" class="panel"><p class="muted mb-4">{{detail.gps_note}} Le coordinate precise non vengono esposte per la regola di privacy locale.</p><TrendChart :rows="detail.track" x="elapsed_s" :series="[{key:'heart_rate_bpm',label:'FC · bpm',color:'#fb7185'}]"/></div>
   <div class="panel table-wrap"><h2 class="font-semibold mb-4">Lap registrati</h2><table><thead><tr><th>Lap</th><th>Distanza m</th><th>Durata s</th><th>Stile</th><th>Passo /100</th><th>FC</th><th>Bracciate</th><th>SWOLF</th></tr></thead><tbody><tr v-for="l in detail.laps" :key="l.lap_index"><td>{{l.lap_index}}</td><td>{{fmt(l.distance_m)}}</td><td>{{fmt(l.duration_s,1)}}</td><td>{{l.stroke||'—'}}</td><td>{{pace(l.pace_per_100m_s)}}</td><td>{{fmt(l.avg_hr_bpm)}}</td><td>{{fmt(l.total_strokes)}}</td><td>{{fmt(l.swolf)}}</td></tr></tbody></table><p v-if="!detail.laps.length" class="muted py-6">FIT non ancora elaborato o dettaglio non disponibile.</p></div>
  </template></template>


  <template v-if="section==='/builder'"><div class="grid lg:grid-cols-3 gap-5"><div class="panel lg:col-span-2"><h2 class="font-semibold mb-5">Workout Builder</h2><label class="eyebrow block mb-2">Libreria Zoned · MIT · template da adattare</label><div class="flex gap-2"><select v-model="selectedTemplate" class="w-full"><option value="">Scegli una sessione</option><option v-for="t in library" :value="t.id">{{t.nameEn||t.name}}</option></select><UButton color="neutral" @click="loadTemplate">Carica</UButton></div><div class="flex flex-wrap gap-3 mt-5"><input v-model="draft.title" aria-label="Titolo sessione" class="flex-1"/><input type="date" v-model="draft.date" aria-label="Data sessione"/></div><textarea v-model="draft.goal" aria-label="Obiettivo" placeholder="Obiettivo della seduta" class="w-full mt-3"/><div v-for="(b,i) in draft.blocks" :key="i" class="grid grid-cols-2 sm:grid-cols-6 gap-2 mt-4"><input v-model="b.label" aria-label="Blocco" class="sm:col-span-2"/><label class="text-xs text-zinc-400">Ripetizioni<input type="number" v-model.number="b.reps" class="w-full" min="1"/></label><label class="text-xs text-zinc-400">Metri<input type="number" v-model.number="b.distance_m" class="w-full" min="25" step="25"/></label><label class="text-xs text-zinc-400">Recupero s<input type="number" v-model.number="b.rest_s" class="w-full" min="0"/></label><div><select v-model="b.zone" aria-label="Zona"><option v-for="z in ['Z1','Z2','Z3','Z4','Z5','Z6']">{{z}}</option></select><UButton @click="draft.blocks.splice(i,1)" color="neutral" variant="ghost" size="xs">Rimuovi</UButton></div></div><div class="flex gap-3 mt-6"><UButton @click="draft.blocks.push({label:'Serie',reps:4,distance_m:100,zone:'Z2',rest_s:20})" color="neutral" variant="outline">Aggiungi blocco</UButton><UButton @click="makePreview">Calcola anteprima</UButton></div><p class="muted mt-4">Le zone sono convenzioni allenanti; i ritmi precisi richiedono una CSS valida. Il piano viene salvato solo dopo l’anteprima e non viene inviato a Garmin.</p></div>
   <div class="panel"><h2 class="font-semibold mb-4">Test CSS 400/200</h2><p class="muted mb-4">Prove massimali della stessa giornata, stessa vasca e recupero completo. Non usare ripetute ordinarie come test.</p><label class="text-xs block">Data<input type="date" v-model="test.date" class="block w-full mt-1 mb-3"/></label><label class="text-xs block">400 m · secondi<input type="number" v-model.number="test.t400" class="block w-full mt-1 mb-3"/></label><label class="text-xs block">200 m · secondi<input type="number" v-model.number="test.t200" class="block w-full mt-1 mb-3"/></label><select v-model.number="test.pool" aria-label="Lunghezza vasca"><option :value="25">Vasca 25 m</option><option :value="50">Vasca 50 m</option></select><label class="text-xs flex gap-2 mt-4"><input type="checkbox" v-model="test.maximal"/>Confermo protocollo e recupero completo</label><UButton @click="testCss" class="mt-4">Calcola CSS</UButton><p class="muted mt-5" v-if="css">Riferimento: {{pace(css.pace_100_s)}} /100 m · {{css.date||css.long_day}}</p><div v-for="(range,z) in css?.zones||{}" class="muted mt-2">{{z}} · {{pace(range[0])}}–{{pace(range[1])}} /100 m</div></div></div>
   <div v-if="preview" class="panel border-green-800"><h2 class="font-semibold text-green-400 mb-3">Anteprima da confermare</h2><p class="text-lg">{{preview.preview.title}} · {{preview.preview.date}}</p><p v-if="preview.preview.total_m" class="metric mt-3">{{fmt(preview.preview.total_m)}} m</p><p v-for="b in preview.preview.blocks" class="muted mt-2">{{b.label}}: {{b.reps}} × {{b.distance_m}} m · {{b.zone}} · recupero {{b.rest_s}}s</p><p v-if="preview.preview.pace_100_s" class="metric">{{pace(preview.preview.pace_100_s)}} /100 m</p><UButton class="mt-5" @click="savePreview">Conferma e salva</UButton></div>
  </template>


